// Writes src/generated/http-status.ts from the table below. Run: node scripts/gen-http-status.mjs
import { writeFileSync } from 'node:fs';

const table = [
  ['NotFound', 404, 'OrderNotFound'],
  ['Conflict', 409, 'InvalidTransition'],
  ['BadRequest', 400, 'Error'],
];

const lines = [
  '// This file is generated by scripts/gen-http-status.mjs. Do not edit it by hand.',
  '',
  'export const httpStatus = {',
  ...table.map(([name, code]) => `  ${name}: ${code},`),
  '} as const;',
  '',
  'export const statusForError: Record<string, number> = {',
  ...table.map(([, code, error]) => `  ${error}: ${code},`),
  '};',
  '',
];

writeFileSync(new URL('../src/generated/http-status.ts', import.meta.url), lines.join('\n'));
